const rawText = $input.first()?.json?.output ?? "";

function safeParseJson(text) {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start === -1 || end === -1 || end <= start) return null;
  const jsonString = text.substring(start, end + 1);
  try { return JSON.parse(jsonString); } catch { return null; }
}

const parsed = safeParseJson(rawText);

if (!parsed) {
  return [{
    json: {
      accion: "INFO",
      lead_tipo: "ADULTO",
      origen: "ORGANICO",
      intencion: "INFO",
      completitud: "BAJA",
      instruccion: "Responder de forma general y pedir 1 dato clave para orientar.",
      mensaje: rawText,
      es_texto: true,
      es_audio: false,
      es_imagen: false,
      es_pdf: false,
      parse_error: true
    }
  }];
}

return [{ json: parsed }];

const headers = $input.first().json.headers || {};
const apiKey = headers['x-api-key'];

const API_KEY_VALIDA = 'fla-2026-Clas3sd31ngl3s';

if (!apiKey || apiKey !== API_KEY_VALIDA) {
  return [{
    json: {
      success: false,
      error: 'Unauthorized'
    },
    status: 401
  }];
}

return $input.first();
